        fixture.sourceReactor = reactor; fixture.sourceImages = images; fixture.sourceExtension = extension; fixture.sourceChild = child;
        // Native writeImage mints the definition identity. Target the stable
        // authored child, not the definition's obsolete DXF source alias.
        fixture.sourceReactor.extData.at(5)->addString(1005, "E131");
