    constexpr std::size_t imageIndexNodeBytes =
        sizeof(dx_ifaceImg*) + 2u * sizeof(void*);
    constexpr std::size_t typedEntityListNodeBytes =
        dx_iface::TypedEntityListNodeBytes;
    if (!commonEntityCollectionsEmpty(emptyImage))
        return fail("IMAGE retained-byte control assumptions changed");
    const std::size_t expectedEmptyImageEntityBytes =
        sizeof(dx_ifaceImg) + commonEntityStringBytes(emptyImage)
        + typedEntityListNodeBytes;
    const std::size_t expectedEmptyImageBytes =
        expectedEmptyImageEntityBytes + imageIndexNodeBytes;
    if (emptyImageBytes.typedEntityCaptureFailed
        || emptyImageBytes.typedEntityRetainedBytes
            != expectedEmptyImageBytes)
        return fail("IMAGE index-node storage was not byte-accounted exactly");
    DRW_Image clippedImage;
