            if (!sawGroup4 || (object.hasRawValues
                && object.rawValues.size() != object.groups.size()))
                return false;
            const bool hasAsciiLexemes = object.hasRawValues
                && std::any_of(
                object.rawValues.begin(), object.rawValues.end(),
                [](const std::string& rawValue) { return !rawValue.empty(); });
            object.groups.insert(object.groups.begin()
                    + static_cast<std::ptrdiff_t>(insertAt),
                DRW_Variant(40, value));
            if (object.hasRawValues) {
                object.rawValues.insert(object.rawValues.begin()
                        + static_cast<std::ptrdiff_t>(insertAt),
                    hasAsciiLexemes ? lexeme : std::string());
                if (object.rawValues.size() != object.groups.size())
                    return false;
            }
