    if (!overRecords.dxfClassCaptureFailed || !overRecords.dxfClasses.empty()
        || overRecords.dxfClassRetainedRecords != kMaxRecords)
        return fail("typed CLASSES record limit was not sticky and bounded");

    dx_data overBytes;
    overBytes.dxfClassRetainedBytes = kMaxBytes - expectedBytes + 1u;
    dx_iface overBytesIface;
