bool renderSettingsTypedCaptureLimitsFailClosed() {
    DRW_RenderSettings settings;
    settings.name = "generated-object-name";
    settings.m_name = "generated-preset";
    settings.m_environmentImageFilename = "generated-env.hdr";
    settings.m_description = "generated description";
    settings.m_longs = {1, 2};
    settings.m_strings = {"generated-preset", "generated-env.hdr",
                          "generated description"};
    settings.m_bools = {true, false};
    settings.m_shorts = {3};
    settings.m_bytes = {4};
    settings.m_doubles = {1.25};
    const std::size_t expectedValues = settings.m_longs.size()
        + settings.m_strings.size() + settings.m_bools.size()
        + settings.m_shorts.size() + settings.m_bytes.size()
        + settings.m_doubles.size();
    std::size_t expectedBytes = sizeof(DRW_RenderSettings)
        + settings.name.size() + 1u
        + settings.m_name.size() + 1u
        + settings.m_environmentImageFilename.size() + 1u
        + settings.m_description.size() + 1u
        + settings.m_longs.size() * sizeof(std::int32_t)
        + settings.m_bools.size() * sizeof(bool)
        + settings.m_shorts.size() * sizeof(std::int32_t)
        + settings.m_bytes.size() * sizeof(std::int32_t)
        + settings.m_doubles.size() * sizeof(double)
        + settings.m_strings.size() * sizeof(UTF8STRING);
    for (const UTF8STRING& value : settings.m_strings)
        expectedBytes += value.size() + 1u;
    expectedBytes += 2u * sizeof(void*);

    dx_data captured;
    dx_iface captureIface;
    captureIface.cData = &captured;
    captureIface.addRenderSettings(settings);
    if (captured.renderSettingsCaptureFailed
        || captured.renderSettings.size() != 1u
        || captured.renderSettingsRetainedRecords != 1u
        || captured.renderSettingsRetainedValues != expectedValues
        || captured.renderSettingsRetainedBytes != expectedBytes)
        return fail("typed RenderSettings callback copy was not bounded and accounted");

    if (expectedBytes > DRW::kMaxDxfBinaryPayloadBytes)
        return fail("typed RenderSettings generated estimate exceeds its budget");
    dx_data exact;
    exact.renderSettingsRetainedBytes =
        DRW::kMaxDxfBinaryPayloadBytes - expectedBytes;
    dx_iface exactIface;
    exactIface.cData = &exact;
    exactIface.addRenderSettings(settings);
    if (exact.renderSettingsCaptureFailed || exact.renderSettings.size() != 1u
        || exact.renderSettingsRetainedRecords != 1u
        || exact.renderSettingsRetainedValues != expectedValues
        || exact.renderSettingsRetainedBytes
            != DRW::kMaxDxfBinaryPayloadBytes)
        return fail("typed RenderSettings exact byte cap was not admitted");

    const auto rejected = [&settings](const std::string& label,
                                      std::size_t retainedBytes,
                                      std::size_t retainedRecords,
                                      std::size_t retainedValues) {
        dx_data data;
        data.renderSettingsRetainedBytes = retainedBytes;
        data.renderSettingsRetainedRecords = retainedRecords;
        data.renderSettingsRetainedValues = retainedValues;
        dx_iface iface;
        iface.cData = &data;
        iface.addRenderSettings(settings);
        iface.addRenderSettings(settings);
        if (!data.renderSettingsCaptureFailed || !data.renderSettings.empty()
            || data.renderSettingsRetainedRecords != retainedRecords
            || data.renderSettingsRetainedValues != retainedValues
            || data.renderSettingsRetainedBytes != retainedBytes)
            return fail("typed RenderSettings " + label
                        + " limit did not refuse copy and remain sticky");

        const auto nonce = std::chrono::steady_clock::now()
                               .time_since_epoch()
                               .count();
        const std::filesystem::path output =
            std::filesystem::temp_directory_path()
            / ("libdxfrw-render-settings-typed-limit-" + label + "-"
               + std::to_string(nonce) + ".dxf");
        if (std::filesystem::exists(output))
            return fail("typed RenderSettings guard output path unexpectedly exists");
        if (iface.fileExport(output.string(), DRW::AC1027, false, &data, true))
            return fail("export passed after typed RenderSettings capture rejection");
        if (!std::filesystem::exists(output))
            return true;
        std::error_code ignored;
        std::filesystem::remove(output, ignored);
        return fail("rejected typed RenderSettings capture published a DXF");
    };
    if (!rejected("bytes-one-over",
                  DRW::kMaxDxfBinaryPayloadBytes - expectedBytes + 1u,
                  0u, 0u)
        || !rejected("records", 0u, 100000u, 0u)
        || !rejected("values", 0u, 0u, 4000000u))
        return false;
    return true;
}

