        DRW_AssociativeObject network("ACDBASSOCNETWORK");
        network.handle = 0xDu;
        network.parentHandle = associationDictionary.handle;
        network.reactorHandles.push_back(associationDictionary.handle);
        network.m_classVersion = 1u;
